  ('a9640dbf-3270-5908-bf77-1a0844ca6c12', 'work-office', 'Make sure Dave stays <b>in the loop</b> on any pricing changes.', 'B1', 21),
  ('9c7f4769-c35d-5b76-976e-f308c8fcac9c', 'work-office', 'Just keeping you <b>in the loop</b> - we pushed the launch to Friday.', 'B1', 22),
  ('008405d0-efff-5290-b44d-d21ad664fc19', 'work-office', 'Can you keep me <b>in the loop</b> on where this lands?', 'A2', 23),
  ('ffaafdb1-5eee-5e8d-a103-007eb31e5584', 'work-office', 'If you see anything off in the report, just <b>flag it</b> for me.', 'A2', 24),
  ('56747879-e819-54f7-940e-e167e5115105', 'work-office', 'I <b>flagged it</b> to my manager but haven''t heard back yet.', 'B2', 25),
  ('04b2cc15-a4e2-5b2e-9f25-ef5342ed58ff', 'work-office', 'Good catch - I''ll <b>flag it</b> with the dev team this morning.', 'B2', 26),
  ('0ef8ca3b-49af-53d2-a0ed-4405ee4e1c53', 'work-office', 'Let me check with finance and <b>get back to you</b> by end of day.', 'A2', 27),
  ('62faad58-3011-5e99-947c-86938750bbab', 'work-office', 'Sorry for the delay - I''ll <b>get back to you</b> first thing tomorrow.', 'B1', 28),
  ('782e466a-34c2-5044-adf1-c42f0397d465', 'work-office', 'She said she''d <b>get back to me</b>, but it''s been a week now.', 'B1', 29),
  ('405145e5-1c1f-519a-9ee2-8ac4af46d73e', 'work-office', '<b>Let me know</b> if that time works for you.', 'A1', 30),
  ('d9ac1ac5-5430-5210-ab20-bb19b8869daf', 'work-office', '<b>Let me know</b> what you think and I''ll make the changes.', 'A2', 31),
  ('a50eae6f-7c3c-5ff3-9f2d-0051ef6c76b8', 'work-office', 'Any questions, just <b>let me know</b>.', 'A2', 32),
  ('7f0306b0-49bd-5941-95c2-829c6779bb4f', 'work-office', '<b>Shoot me an email</b> with the details and I''ll take a look.', 'A2', 33),
  ('ab1e632e-156e-58e4-b8da-d2f257a72c9b', 'work-office', 'If you need anything while I''m out, just <b>shoot me a message</b>.', 'B2', 34),
  ('00bd5fff-2faa-5f87-90b0-044162d14319', 'work-office', '<b>Shoot me an email</b> whenever you get a chance - no rush.', 'B2', 35),
  ('bbd7cda5-9b4a-52e8-9d94-f108f247d62b', 'work-office', 'Just <b>checking in</b> to see if you had a chance to review the draft.', 'B1', 36),
  ('8ad26474-03ee-5afa-bc62-49519f85f357', 'work-office', 'Hey, <b>checking in</b> on the status of that invoice.', 'B1', 37),
  ('a42cc8f5-0eed-5a13-9060-72a047cffb95', 'work-office', 'Wanted to <b>check in</b> before the weekend - are we still on track?', 'A2', 38),
  ('c4ebf4df-c103-527f-8cc5-bd26ec2e4033', 'work-office', 'I''d love to help, but I''ve got a lot <b>on my plate</b> right now.', 'B2', 39),
  ('11527532-a87d-5483-a2ea-b17d5ee1df14', 'work-office', 'Can this wait till next week? I''ve got too much <b>on my plate</b> to even look at it today.', 'C2', 40),
  ('0041f8df-d418-57bf-adae-47343f13838f', 'work-office', 'What''s <b>on your plate</b> this week? Anything I can take off you?', 'B1', 41),
  ('5a551ab4-7a04-5c37-8e09-c2b3819ad739', 'work-office', 'I''m really sorry, I <b>dropped the ball</b> on sending that invoice.', 'B2', 42),
  ('7703bd66-e199-5712-939f-6ed4b251eea8', 'work-office', 'We can''t afford to <b>drop the ball</b> on this client.', 'B1', 43),
  ('aa93ffeb-2031-5322-ba10-7fbfe17271cb', 'work-office', 'Honestly, marketing <b>dropped the ball</b> on this one. Nobody followed up with the leads.', 'B2', 44),
  ('5783d0be-f945-5665-b7bd-2a220d4a400b', 'work-office', 'While Dana''s on leave, we''ll all need to <b>pick up the slack</b>.', 'B2', 45),
  ('378ba95d-c88e-5192-96a7-aaed031ff0f9', 'work-office', 'Thanks for <b>picking up the slack</b> last week. I was totally swamped.', 'B2', 46),
  ('329ba177-90c9-536d-9d1e-5bff8624376f', 'work-office', 'If one person''s out, someone else has to <b>pick up the slack</b>.', 'B2', 47),
  ('0f1330ae-8ad1-53f4-8e60-2011199d68b8', 'work-office', 'I use a checklist to <b>stay on top of</b> my deadlines.', 'B1', 48),
  ('9f6d3404-974e-55f6-866e-ccd4425241c3', 'work-office', 'You''ve got to <b>stay on top of</b> your emails or they get out of hand.', 'B1', 49),
  ('7d98358b-8857-51cd-84c9-8a821a007c7c', 'work-office', 'She''s really good at <b>staying on top of</b> the project timeline.', 'B1', 50),
  ('601e2912-29d4-5333-85e1-a3162ae36daf', 'work-office', 'Don''t worry about the deployment, I''m <b>on top of it</b>.', 'B2', 51)
insert into public.sentences (id, deck_id, content, level_id, position) values
  ('9b63d326-46d5-5a1c-bcef-2ef37f0d4796', 'work-office', 'The client asked for an update, but we''re already <b>on top of it</b>.', 'B1', 52),
  ('22b4311c-7527-53c3-b2bc-9bc6000f9b05', 'work-office', 'Good, sounds like you''re <b>on top of it</b>.', 'A1', 53),
  ('b960c712-c0a5-599e-9352-d880236a59d1', 'work-office', 'I just don''t have the <b>bandwidth</b> to take on another project this quarter.', 'B2', 54),
  ('31deccbe-eda9-5808-8d42-836bb1054caa', 'work-office', 'Do you have the <b>bandwidth</b> to help me with this by Friday?', 'A2', 55),
  ('7ddfbb19-74f6-541d-a24c-e653dcdc1447', 'work-office', 'Let''s revisit it next month when the team has more <b>bandwidth</b>.', 'B2', 56),
  ('5331b7ce-dce5-5ff8-a569-2439e75cc5c4', 'work-office', 'I''m <b>juggling a few things</b> right now, so give me an hour.', 'B2', 57),
  ('63056245-a955-50f1-99cb-8ca8fa0d411a', 'work-office', 'She''s <b>juggling</b> three projects and onboarding a new hire at the same time.', 'C1', 58),
  ('9f33606a-9667-5abe-b26a-fbf1af788cd5', 'work-office', 'Sorry for the slow reply, I''ve been <b>juggling</b> a lot lately.', 'C1', 59),
  ('653efdb6-9538-51d3-b393-9efbb55424ab', 'work-office', 'Let''s <b>get the ball rolling</b> on hiring before the holidays.', 'B2', 60),
  ('0cbbe5dc-e2f8-5ae0-b01c-fce88f863dc5', 'work-office', 'I sent the kickoff email just to <b>get the ball rolling</b>.', 'B1', 61),
  ('e1c8d2e2-3529-5a16-a4a2-79925d2d21e8', 'work-office', 'Once legal signs off, we can <b>get the ball rolling</b>.', 'B1', 62),
  ('2909b061-fd6d-5cd5-8d3c-194a39bbbd6b', 'work-office', 'Don''t worry about the printer, I''ll <b>take care of it</b>.', 'B2', 63),
  ('56f33013-0bb5-5f26-9447-73a265810d0c', 'work-office', 'Can you <b>take care of</b> the catering for the offsite?', 'A2', 64),
  ('bdd1f395-5977-5b46-b1e9-985ba5f9cbd0', 'work-office', 'It''s already <b>taken care of</b>.', 'A2', 65),
  ('1dcd50e7-1fa5-5053-af8f-67cc2c41e3b6', 'work-office', 'Let''s put the redesign on the <b>back burner</b> until Q3.', 'B2', 66),
  ('4c5ffa5a-d110-52a9-9954-452bff61d61a', 'work-office', 'That idea''s been on the <b>back burner</b> for months.', 'A2', 67),
  ('4dd1fe52-8885-5e3c-b82a-02ae3bacbc5c', 'work-office', 'We had to move it to the <b>back burner</b> when the outage hit.', 'B2', 68),
  ('868c8024-fef0-5db7-8706-3faf1e520ec2', 'work-office', 'I''ll <b>follow up</b> with them if we don''t hear back by Thursday.', 'C1', 69),
  ('62859885-d979-56ad-83eb-7e930e22493e', 'work-office', 'Just <b>following up on</b> my last email about the contract.', 'A1', 70),
  ('a1e03768-b5b5-5855-9da3-45f3e4bc0c33', 'work-office', 'Thanks for the meeting. I''ll send a quick <b>follow-up</b> with next steps.', 'B2', 71),
  ('19372391-2723-5445-a606-27c93849fdd4', 'work-office', 'We''re a little <b>behind schedule</b> on the launch, so I might need another day or two.', 'C1', 72),
  ('96399fbf-9e18-5fa9-a774-c850400d2df8', 'work-office', 'Honestly, the whole project''s been <b>behind schedule</b> since the vendor dropped out.', 'C1', 73),
  ('2826cf81-64d3-55ff-9072-c9133cfb7b56', 'work-office', 'If we don''t get sign-off today, we''ll fall even further <b>behind schedule</b>.', 'C2', 74),
  ('b748d92b-d9f2-5115-84c6-322fc14fd7c4', 'work-office', 'We''re still <b>on track</b> to ship by Friday.', 'A2', 75),
  ('1727bf23-2e15-5e34-a1f0-45580376687e', 'work-office', 'Just wanted to confirm we''re <b>on track</b> for the end-of-quarter numbers.', 'B2', 76),
  ('4c3f2dc7-9edc-5605-9497-f5585b54e14b', 'work-office', 'The redesign slipped, but everything else is <b>on track</b>.', 'B2', 77),
  ('a57490a7-2be9-5da8-9e4c-89c063ec6917', 'work-office', 'It''s <b>crunch time</b> now — everything ships Monday, so heads down this week.', 'C1', 78),
  ('39bd5609-4007-5173-bcbf-53611f0e1aee', 'work-office', 'We''re heading into <b>crunch time</b>, so let''s punt anything non-urgent to next sprint.', 'C2', 79),
  ('57460cc1-fb09-50de-9920-74c48fbe4ce7', 'work-office', 'I know it''s <b>crunch time</b>, but don''t burn yourselves out.', 'C1', 80),
  ('143bfa80-ab0b-5af1-afe2-cdf691c4662e', 'work-office', 'Can we <b>push back</b> the deadline to Thursday? The data came in late.', 'B2', 81),
  ('7d009419-fcf1-5de6-9e0a-31b9a0286861', 'work-office', 'They ended up <b>pushing back</b> the launch two weeks.', 'B1', 82),
  ('d4a3e03e-96ee-5057-a4e8-18d5ad7605be', 'work-office', 'Let''s <b>push back</b> our one-on-one to the afternoon.', 'B1', 83),
  ('1ae5201e-e696-5fb9-a597-92a70d77bc26', 'work-office', 'It came <b>down to the wire</b>, but we submitted the proposal with five minutes to spare.', 'B2', 84),
  ('6f900bd4-5b31-54ab-a410-ddf169f58174', 'work-office', 'This is going <b>down to the wire</b> — QA''s still finding bugs an hour before release.', 'C1', 85),
  ('e0d53a62-f222-578c-a439-7657a1ecb3b9', 'work-office', 'Every quarter it''s the same thing, we''re always <b>down to the wire</b>.', 'B2', 86),
  ('d84d4ec6-b538-51a3-b54d-c1efeb775ac7', 'work-office', 'Good news — we''re actually <b>ahead of schedule</b> on the migration.', 'B2', 87),
  ('ec65d7e9-242e-535c-9447-ba15200266f4', 'work-office', 'The contractor finished the buildout a week <b>ahead of schedule</b>.', 'B2', 88),
  ('f8865a58-8db8-5329-a86b-7b8355dd1f1f', 'work-office', 'If everything holds, we''ll wrap this up <b>ahead of schedule</b>.', 'B2', 89),
  ('99f06e8d-22d5-50ea-af28-0497c0736f54', 'work-office', 'We''re so close on this deal — let''s do whatever it takes to <b>get it across the finish line</b>.', 'C2', 90),
  ('a7e6a485-4923-51f9-9cf9-2fb57d61db21', 'work-office', 'One more approval and we can <b>get this across the finish line</b>.', 'B1', 91),
  ('a633fe67-8014-5c31-b7ab-45ca43b7f08c', 'work-office', 'Thanks, everyone, for helping <b>get it across the finish line</b> before the holidays.', 'B1', 92),
  ('4cb32c8d-e793-5f49-b191-5a7b3ccbcecf', 'work-office', 'I can''t really talk right now, I''m <b>up against a deadline</b>.', 'B2', 93),
  ('4bcc3f45-6022-59c5-b956-2bb6841bd2c7', 'work-office', 'The team''s <b>up against a deadline</b> on the RFP, so bear with us.', 'B2', 94),
  ('20a72275-9411-5773-bf3d-e34b40748e5c', 'work-office', 'We''re really <b>up against it</b> this week with two launches.', 'B1', 95),
  ('18f030bc-8fac-5172-bc28-9dd64c7df7fc', 'work-office', 'It''s a pretty <b>tight deadline</b>, but I think we can make it work.', 'B2', 96),
  ('a6cb8197-e5c7-544b-bd10-d069d131654b', 'work-office', 'They gave us a really <b>tight deadline</b> — end of day Friday.', 'B2', 97),
  ('c7487b3e-faf1-5265-9639-6cb5ffb8143f', 'work-office', 'That''s a really <b>tight deadline</b> — I''d want to check with the team before I commit.', 'C1', 98),
  ('68907fb5-9438-5430-b3a6-19f4aebe1245', 'work-office', 'If we ship the beta first, that''ll <b>buy us some time</b> on the full release.', 'B2', 99),
  ('7b973542-3bec-5c27-85c7-158a48f846fd', 'work-office', 'Can you stall the client for a day? Just <b>buy me some time</b>.', 'A2', 100),
  ('a0ee38bf-69b5-5271-9723-d1cb402445fe', 'work-office', 'Pushing the demo back <b>buys us a little time</b> to fix the bugs.', 'B2', 101),
  ('267a4219-807c-5470-acc6-0a95c921cd25', 'work-office', 'Can you send me the deck <b>by end of day</b>?', 'A1', 102),
  ('a3799f58-535e-5195-8f3a-d16fcb2a6bb1', 'work-office', 'I''ll have the numbers to you <b>by EOD</b>.', 'A1', 103),
  ('b92239d8-7061-5e80-9d1f-93eeeb8c0c01', 'work-office', 'Let''s aim to wrap this up <b>by end of day</b> tomorrow.', 'B2', 104),
  ('c4cb4bd7-8f9d-58f4-9809-a67ef5e51b77', 'work-office', 'Hey, you wanna <b>grab lunch</b> after the standup?', 'B2', 105),
  ('b01370e5-8e56-559c-8d61-55e0886ddfa6', 'work-office', 'We usually <b>grab lunch</b> around noon if you feel like joining.', 'C1', 106),
  ('7e70033c-8f38-5a5d-87b7-d4d5771b63ca', 'work-office', 'I''m starving—let''s <b>grab lunch</b> before the one o''clock.', 'C1', 107),
  ('925cf0fd-9b1f-57a2-b415-316a8c9d5b98', 'work-office', 'Can you <b>cover for</b> me Friday? I''ve got a doctor''s appointment.', 'B2', 108),
  ('f7269fdb-3641-5d36-8f42-8096c36c735c', 'work-office', 'Thanks for <b>covering for</b> me while I was out sick.', 'A2', 109),
  ('f8d1d9e4-a9fd-579e-b76f-ee347deee24f', 'work-office', 'Someone needs to <b>cover for</b> Dana at the front desk during her break.', 'B2', 110),
  ('2572c5e8-2463-5665-8aaf-7e4272a797c2', 'work-office', 'I''ll be <b>out of office</b> next week, so loop in Priya on anything urgent.', 'C1', 111),
  ('fb52115f-b604-577d-b452-4992efc5c080', 'work-office', 'Did you set your <b>out of office</b> before you left?', 'A1', 112),
  ('7aa95d70-3763-5a86-9618-9b612f6cb6ef', 'work-office', 'Heads-up, I''m <b>out of office</b> Thursday and Friday for a conference.', 'B1', 113),
  ('86acee03-1438-5b1c-839e-99803a33cf8e', 'work-office', 'I <b>work from home</b> on Fridays.', 'A1', 114),
  ('a3a6f434-87ef-55a9-b765-dba950ac24b5', 'work-office', 'Can I <b>work from home</b> tomorrow? The plumber''s coming.', 'A2', 115),
  ('1273ffbf-2553-57c8-846f-7df7b7ea720e', 'work-office', 'Half the team <b>works from home</b> now, so the office is pretty empty.', 'B1', 116),
  ('c7defee2-fdaa-545d-9794-1e559bc3f36b', 'work-office', 'Just <b>a heads-up</b>—the client''s running about fifteen minutes late.', 'B2', 117),
  ('f2000f71-95c0-52a7-b3dd-91e391510f0d', 'work-office', 'Thanks for the <b>heads-up</b> about the fire drill.', 'A2', 118),
  ('84948eb5-a928-526d-911d-177be4aa089e', 'work-office', 'Give me a <b>heads-up</b> if the meeting time moves.', 'A2', 119),
  ('ccf0979c-f4f3-59ce-8de7-ae77bc582d87', 'work-office', 'Let''s <b>wrap up</b> here—we''re already over time.', 'B1', 120),
  ('c97edccf-a515-5e52-8755-a66494b97f31', 'work-office', 'I just need to <b>wrap up</b> a couple of emails and then I''m free.', 'B1', 121),
  ('0799e772-5b06-51a7-a266-708176c5d1bd', 'work-office', 'Are you almost done, or still <b>wrapping up</b>?', 'B1', 122),
  ('bb64f27b-f0d1-5bc2-930b-aaeaf56f8429', 'tech-software-development', 'Tests are green and QA signed off, so let''s just <b>ship it</b>.', 'B2', 0),
  ('cb7997c2-ccc8-5eb9-9616-e5ff32c18865', 'tech-software-development', 'Honestly it''s good enough for v1 — <b>ship it</b> and we''ll iterate.', 'C1', 1),
  ('d1d87f28-2e22-5df3-9efa-a0dde109606a', 'tech-software-development', 'Stop polishing the CSS, man, just <b>ship it</b>.', 'B2', 2),
  ('d2f71a85-668b-5699-890f-cead414969f9', 'tech-software-development', 'Please don''t <b>push to prod</b> on a Friday afternoon.', 'C1', 3),
  ('f79ee78a-41c6-57fb-9e48-71c1874b5d5b', 'tech-software-development', 'We <b>pushed to prod</b> around two and the error rate spiked instantly.', 'C1', 4),
  ('62711fdd-a1a0-59b6-8f4e-cdcaebacd5db', 'tech-software-development', 'Who <b>pushed to prod</b> without running the migration first?', 'B2', 5),
  ('866c9fa0-eb33-50e5-bd2c-92deb26220ea', 'tech-software-development', 'Can you review this so I can <b>merge the PR</b> before standup?', 'B2', 6),
  ('bd3e2afe-b689-5f9a-baba-81ffa41a068b', 'tech-software-development', 'I''ll <b>merge the PR</b> once CI passes.', 'B2', 7),
  ('d7e0f81f-c8de-5977-8ea1-4cb8d7b1a6b9', 'tech-software-development', 'Don''t <b>merge the PR</b> yet — I still have a couple of comments.', 'C1', 8),
  ('ae3ffe30-9d62-5895-a552-f6235fdd1b0f', 'tech-software-development', 'Let me <b>spin up</b> a staging environment so you can test it.', 'B1', 9),
  ('bcca8d79-c702-5e0a-ad5a-1e29c94b4f44', 'tech-software-development', 'We can <b>spin up</b> a couple more instances if traffic gets crazy.', 'B2', 10),
  ('1ad5ecf3-bb9c-563b-ba84-2d22564319aa', 'tech-software-development', 'I <b>spun up</b> a quick Postgres container to reproduce the bug.', 'B2', 11),
  ('3726c23e-f647-5a6c-be52-5d5d7368fe03', 'tech-software-development', 'The deploy broke checkout, so we had to <b>roll back</b>.', 'B2', 12),
  ('fa493f6a-6c95-5011-94c5-a06bffdf7add', 'tech-software-development', 'If anything looks off, just <b>roll back</b> to the last release.', 'B1', 13),
  ('7aabfdb7-2313-5a8e-83cb-0599de0f2829', 'tech-software-development', 'We <b>rolled back</b> within five minutes, so most users never noticed.', 'B2', 14),
  ('cff3cb36-ce1f-556c-ad0d-060b98e36200', 'tech-software-development', 'The payment bug was critical, so we <b>pushed a hotfix</b> overnight.', 'C1', 15),
  ('19e93127-a305-5dcf-81a9-5778f5c0b838', 'tech-software-development', 'Can we <b>push a hotfix</b> for this, or does it have to wait for the release?', 'B1', 16),
  ('4ff2cebc-9fb8-5190-afda-9ef1f9f81551', 'tech-software-development', 'It''s a one-line change — I''ll just <b>push a hotfix</b> real quick.', 'C1', 17),
  ('2df90a2e-be8a-51fd-9d3a-8c9bc6dcc6b5', 'tech-software-development', 'If it''s not on the board, <b>open a ticket</b> so we don''t lose track of it.', 'C1', 18),
  ('db8c84bf-0cb7-5a8e-867f-87d6d7829e53', 'tech-software-development', 'I''ll <b>open a ticket</b> for the flaky test and assign it to myself.', 'C1', 19),
  ('c69c8824-675e-57d3-af5a-e480218ff36c', 'tech-software-development', 'Did you <b>open a ticket</b> for that, or is it just buried in Slack somewhere?', 'B2', 20),
  ('5ca18855-6232-56b2-9d4d-cfc72825b02c', 'tech-software-development', 'We''re planning to <b>cut a release</b> on Thursday if everything stays stable.', 'B2', 21),
  ('ef065088-4a20-5ce1-a590-58a0b15959f6', 'tech-software-development', 'Once this PR lands, I''ll <b>cut a release</b> and tag it.', 'B2', 22),
  ('09eadbdc-ba43-5eba-9a5f-4e98d6ce70d2', 'tech-software-development', 'Let''s <b>cut a release</b> candidate and let QA hammer on it.', 'C1', 23),
  ('cb39fa89-c5db-54f0-a2f5-34e83fcdf248', 'tech-software-development', 'We''re in a <b>code freeze</b> until the launch, so no new features.', 'B2', 24),
  ('0ef4dc3f-38f9-5aab-a3a7-7742fcbc0a54', 'tech-software-development', '<b>Code freeze</b> starts Monday — get your PRs merged this week.', 'C1', 25),
  ('1658fe47-34e8-519d-b2b7-b011aa0d8c9e', 'tech-software-development', 'Is this a hard <b>code freeze</b>, or can we still land bug fixes?', 'B2', 26),
  ('d6de7f8d-202a-550c-93f8-27be928d5c43', 'tech-software-development', 'We''re going to <b>roll out</b> the new dashboard to 10% of users first.', 'B1', 27),
  ('28ebd520-2dbc-56ea-9e2a-8835d782535a', 'tech-software-development', 'Let''s <b>roll out</b> the feature gradually and watch the metrics.', 'C1', 28),
  ('25326332-f171-5cd2-8191-072336672896', 'tech-software-development', 'They <b>rolled out</b> the update to everyone at once and it melted the servers.', 'B2', 29),
  ('d3ddf8d8-43b1-5726-aa19-9c020d477fd8', 'tech-software-development', 'I went through the diff — <b>looks good to me</b>, ship it.', 'B1', 30),
  ('28fd37a0-123b-561a-83ee-371cb5ca6a61', 'tech-software-development', 'Left one tiny nit, but otherwise it <b>looks good to me</b>.', 'B2', 31),
  ('5685df2f-ddc1-5078-892d-1cbc890e266a', 'tech-software-development', 'Approved. <b>Looks good to me</b>.', 'A1', 32),
  ('ec084784-3aaa-57d0-a28a-75c27499fd91', 'tech-software-development', 'Run the tests locally first so you don''t <b>break the build</b>.', 'B2', 33),
  ('1c763b05-5f84-549d-b123-31d53f8dd2fe', 'tech-software-development', 'Someone <b>broke the build</b> on main — nobody can deploy until it''s green.', 'C1', 34),
  ('854afb13-a8fe-53f4-ac8f-6e546081beaa', 'tech-software-development', 'My bad, I <b>broke the build</b>; pushing a fix now.', 'B2', 35),
  ('80905c33-0b42-5ad9-b6b3-1b27086bd121', 'tech-software-development', 'CI''s green and QA signed off — we''re <b>good to go</b> for the deploy.', 'C1', 36),
  ('790aa99d-d282-5f02-81bf-6e2cb5249e3b', 'tech-software-development', 'Once you rebase on main, you should be <b>good to go</b>.', 'A2', 37),
  ('b820287d-a4ca-58e5-b089-9a26b17ed158', 'tech-software-development', 'Migration ran clean, so we''re <b>good to go</b>.', 'B2', 38),
  ('544b6f52-0ede-5835-ac92-def9a3f04456', 'tech-software-development', 'I <b>put up a PR</b> — can someone take a look?', 'A2', 39),
  ('d4d0675f-bea6-540b-98af-0dd857040162', 'tech-software-development', 'Go ahead and <b>put up a PR</b> and tag me as a reviewer.', 'B1', 40),
  ('7019591e-efc0-5b61-8d7c-1e9dae3fd1f2', 'tech-software-development', 'I''ll <b>put up a PR</b> after lunch once I clean up the commits.', 'C1', 41),
  ('e7d583bc-9c0d-5ce8-91e8-e7eab426d7ea', 'tech-software-development', 'The happy path works fine, but we''re not handling the <b>edge case</b> where the list is empty.', 'C1', 42),
  ('c5f8bc89-b646-52f2-8ae7-ccdae4035181', 'tech-software-development', 'Most of these bugs are just weird <b>edge cases</b> nobody thought to test.', 'C1', 43),
  ('3da234a7-c37f-5509-998e-ba08ffe52666', 'tech-software-development', 'What happens if the timezone offset is negative? That''s an <b>edge case</b> we need to cover.', 'C2', 44),
  ('a831363d-59ec-5161-8cd2-18bcc41effe2', 'tech-software-development', 'If the config file is missing, it should just <b>throw an error</b> instead of failing silently.', 'C1', 45),
  ('3bd53fa5-4daa-5790-a4a9-f4a3b8fc7d83', 'tech-software-development', 'Why is this <b>throwing an error</b>? The input looks totally valid to me.', 'B1', 46),
  ('5cb8a97e-98dd-50af-8aa1-badbbe12482c', 'tech-software-development', 'Don''t let it crash the whole app, just <b>throw an error</b> and let the caller handle it.', 'C2', 47),
  ('6875338c-9855-529b-a147-c31e86d6e1b8', 'tech-software-development', 'I spent all afternoon trying to <b>track down</b> where this null was coming from.', 'B2', 48),
  ('e5f3ec96-0468-562d-bee9-c247d61f90b5', 'tech-software-development', 'It took us two days to <b>track down</b> the memory leak.', 'B1', 49),
  ('36fc33c0-9c86-59c1-8ffb-aaff89e2f414', 'tech-software-development', 'Can you help me <b>track down</b> why the page is loading so slowly?', 'B1', 50),
  ('3e6dc3b0-4732-546f-99c2-578c78ee1cfa', 'tech-software-development', 'I can''t <b>reproduce the issue</b> locally, it only happens in production.', 'B2', 51),
  ('718f92d0-1e6d-5ca3-b56f-39c07a39dcad', 'tech-software-development', 'Do you have steps to <b>reproduce the issue</b>? I''m not seeing it on my end.', 'B1', 52),
  ('87c81658-9a62-5238-9e4b-7b08e806ed72', 'tech-software-development', 'Once we could <b>reproduce the issue</b> consistently, the fix was pretty quick.', 'C1', 53),
  ('0c135239-e83a-5882-9674-5c97202947d0', 'tech-software-development', 'The <b>root cause</b> turned out to be a caching bug, not the API like we thought.', 'C1', 54),
  ('9945eed3-70d2-5725-bb23-1d64b4738288', 'tech-software-development', 'Let''s not just patch the symptom, we need to find the <b>root cause</b>.', 'B2', 55),
  ('9a540730-49eb-5257-be58-f8965f2b95f1', 'tech-software-development', 'We''re still doing the <b>root cause</b> analysis, but it looks like a race condition.', 'C1', 56),
  ('b9c12cd8-a02e-598a-a38a-81e7dd9e6f90', 'tech-software-development', 'This <b>flaky test</b> fails maybe one in ten runs for no reason.', 'B2', 57),
  ('89315069-4c8e-5757-b806-27e357164c22', 'tech-software-development', 'Can someone look at that <b>flaky test</b> in CI? It keeps blocking merges.', 'C1', 58),
  ('382ed535-3eb3-58cb-a490-24873de0a980', 'tech-software-development', 'I hate <b>flaky tests</b>, you never know if the failure is real or not.', 'B2', 59),
  ('e002e5ef-1d6d-5a46-8fc0-a5e0450e089c', 'tech-software-development', 'Something''s off in prod, let me <b>check the logs</b>.', 'B1', 60),
  ('fc4c252c-2da4-5437-ac30-7a7eb225331b', 'tech-software-development', 'Did you <b>check the logs</b>? There might be a stack trace in there.', 'B2', 61),
  ('e51642e4-48fc-559c-b982-daafc85848f6', 'tech-software-development', 'I <b>checked the logs</b> and there''s a bunch of timeout errors around 3am.', 'B2', 62),
  ('97ad1bfd-3744-53e0-9366-9202ee32f55c', 'tech-software-development', 'I''ve <b>narrowed it down</b> to either the auth service or the database.', 'B2', 63),
  ('60be6ed8-8ad2-5bcf-b814-2a2af087d81c', 'tech-software-development', 'Let''s add some logging so we can <b>narrow it down</b>.', 'B1', 64),
  ('5c1aa507-054a-5cbf-8284-a526010be307', 'tech-software-development', 'We <b>narrowed it down</b> to a single commit that introduced the bug.', 'B2', 65),
  ('f4b51b7a-7677-50cf-b4e3-c629a456b0ea', 'tech-software-development', 'Just paste the full <b>stack trace</b>, I can''t tell what''s failing from that.', 'C2', 66),
  ('817d5c5d-0c15-535c-bd4a-350c5923a90f', 'tech-software-development', 'The <b>stack trace</b> points to line 42 in the parser.', 'B1', 67),
  ('49a809e5-fbcf-52a2-8f50-393fa26501de', 'tech-software-development', 'There''s no <b>stack trace</b>, it just hangs, which makes it way harder to debug.', 'C1', 68),
  ('965bc945-ce0c-5889-af1f-8c892b47c5ba', 'tech-software-development', 'I <b>went down a rabbit hole</b> debugging the linter and completely forgot what I was actually trying to fix.', 'C2', 69),
  ('2c75b822-26f7-54db-91fa-3b949d6a207b', 'tech-software-development', 'Careful, that part of the codebase is a total <b>rabbit hole</b>.', 'B2', 70),
  ('ce577928-f249-5b29-a19f-87348901d2d4', 'tech-software-development', 'I don''t want to <b>go down a rabbit hole</b> on this, let''s just ship a quick fix.', 'C2', 71),
  ('213c02b9-f5a5-504e-aef5-fc733b2f3982', 'tech-software-development', 'The <b>happy path</b> works, but everything breaks the moment there''s bad input.', 'C1', 72),
  ('0b6c6a87-89ea-5dca-b774-d7a743e9def7', 'tech-software-development', 'We only tested the <b>happy path</b>, so of course it fell over in production.', 'B2', 73),
  ('af2544b0-4228-56db-aa86-a93017361aaf', 'tech-software-development', 'Let''s get the <b>happy path</b> working first, then handle the error cases.', 'B2', 74),
  ('e952dc30-7182-5233-8214-e851ec98d443', 'tech-software-development', 'Before we deploy, let me just do a quick <b>sanity check</b> on the config.', 'C1', 75),
  ('6baa9cbf-15df-5a5a-a21c-94db4b23aed6', 'tech-software-development', 'Can you run a <b>sanity check</b> to make sure the data actually loaded?', 'B2', 76),
  ('f7e0e791-ac6b-5cc4-9c34-7ebc54df947d', 'tech-software-development', 'Just as a <b>sanity check</b>, did you save the file before rebuilding?', 'B2', 77),
  ('48207053-6db7-5d56-be2f-c4ed6b31362b', 'tech-software-development', 'I don''t get it, it <b>works on my machine</b>.', 'A2', 78),
  ('c812a445-a080-5209-8c00-43c8aa2d6d49', 'tech-software-development', '''<b>Works on my machine</b>'' isn''t going to help the customer, though.', 'B2', 79),
  ('a8e8592f-7489-5d30-b257-df0c776e4495', 'tech-software-development', 'Classic - it <b>works on my machine</b> but blows up in CI.', 'B1', 80),
  ('5b550ca6-9c50-5a79-9909-96ab85ac0918', 'tech-software-development', 'I''ll bring it up at <b>standup</b> tomorrow morning.', 'B2', 81),
  ('47d03dd0-bcec-53fc-ac06-7afd58750735', 'tech-software-development', 'Can you drop your update in Slack? I''m gonna miss <b>standup</b> today.', 'C1', 82),
  ('fca40ba2-cdcd-5a88-8e6d-a1b3f32aa5e1', 'tech-software-development', 'We spent twenty minutes on one ticket — <b>standup</b> is supposed to be fifteen, tops.', 'C1', 83),
  ('6c95c86f-d29a-56c6-8ce4-ef34a7c87399', 'tech-software-development', 'Let''s <b>sync up</b> after lunch and figure out the API changes.', 'C1', 84),
  ('3e935670-cf3b-5ada-a8f2-a58f97e3b2f5', 'tech-software-development', 'Can we <b>sync up</b> real quick before you push that?', 'B1', 85),
  ('06a5aa8b-82ee-5619-baaf-554dea241907', 'tech-software-development', 'We should <b>sync up</b> with design before we build the whole flow.', 'B2', 86),
  ('b34086ae-3de4-544a-9207-31e31962dedb', 'tech-software-development', 'We shipped it fast, but we took on a ton of <b>tech debt</b>.', 'B2', 87),
  ('652c0ccc-6c03-5717-b305-d8cd25c64619', 'tech-software-development', 'Half of this sprint is just paying down <b>tech debt</b>.', 'B1', 88),
  ('d8c87b7c-fdad-51f7-a299-1b935758b003', 'tech-software-development', 'That workaround is fine for now — just log it as <b>tech debt</b> so we don''t forget.', 'C2', 89),
  ('eb638b33-8b0e-5265-80dc-129bb2c8843c', 'tech-software-development', 'This started as a login page and now it''s a whole dashboard — classic <b>scope creep</b>.', 'C2', 90),
  ('33ec4230-2ff5-57fe-85cd-d7933a3fae4a', 'tech-software-development', 'We need to watch out for <b>scope creep</b> on this one.', 'B1', 91),
  ('9f3a3879-fb94-52ae-ad6c-13ce3c649ee7', 'tech-software-development', 'Every ''small'' request adds up; that''s how <b>scope creep</b> kills a deadline.', 'C1', 92),
  ('024640e3-4b0d-5416-b1c6-fd5a7d8e2698', 'tech-software-development', 'I can''t finish the feature — staging being down is a <b>blocker</b>.', 'B2', 93),
  ('7e492012-2e60-5333-a89c-c5a883d1ede8', 'tech-software-development', 'Any <b>blockers</b> on your end?', 'A1', 94),
  ('43f99f2a-2be6-5292-b7b9-7ccb94553366', 'tech-software-development', 'Waiting on the API key is my only <b>blocker</b> right now.', 'B1', 95),
  ('bdbb843b-8da7-53fd-98e9-1b7b86191af5', 'tech-software-development', 'Good discussion, but let''s <b>take it offline</b> — we''re eating into everyone''s time.', 'C1', 96),
  ('57980e64-37f1-5687-ab51-2ae7c5351e9f', 'tech-software-development', 'That''s a rabbit hole; can you two <b>take it offline</b> and report back?', 'B2', 97),
  ('52ba7e98-a427-52ab-85ee-2565dd4642c5', 'tech-software-development', 'We''ll <b>take this offline</b> and loop the rest of you in later.', 'B2', 98),
  ('be34f7ca-1b4d-5c12-afef-fde314367c08', 'tech-software-development', 'Let''s knock out the <b>low-hanging fruit</b> first, then tackle the hard stuff.', 'C2', 99),
  ('1b099146-263a-5c78-9ff1-e4a89f7babcc', 'tech-software-development', 'Fixing those typos is <b>low-hanging fruit</b> — do it before the demo.', 'C1', 100),
  ('c3627003-a33c-5349-b3fb-1aefdd45adc3', 'tech-software-development', 'There''s a lot of <b>low-hanging fruit</b> in the onboarding flow if we want quick wins.', 'C2', 101),
  ('6bff091e-4e26-5b5a-853d-39cefd6e4392', 'tech-software-development', 'Dark mode is a <b>nice-to-have</b>, not a must-have for launch.', 'B1', 102),
  ('9c60c152-3c7a-505a-8a73-7bbba74ad084', 'tech-software-development', 'Let''s separate the <b>nice-to-haves</b> from the things we actually need.', 'B1', 103),
  ('aa124529-0f52-5ab7-9018-b329564c2eb4', 'tech-software-development', 'Sure, animations would be nice, but that''s a <b>nice-to-have</b> — ship the core flow first.', 'C1', 104),
  ('caa3f88b-72ec-5ab7-8b5b-26a361612bd4', 'tech-software-development', 'Before we start coding, let''s make sure we''re <b>on the same page</b> about the requirements.', 'B2', 105),
  ('d4a9ff3b-f61d-570e-9eef-9443da9e60af', 'tech-software-development', 'Quick recap so everyone''s <b>on the same page</b>.', 'A2', 106),
  ('7ad21b2e-d51e-50a6-901b-9a9e482a28ff', 'tech-software-development', 'I thought we were <b>on the same page</b>, but you built something totally different.', 'B1', 107),
  ('0c281964-d7d7-5a10-b37a-5855bd6a5888', 'tech-software-development', 'Let''s <b>loop in</b> Sarah — she owns that service.', 'B1', 108),
  ('c7dc4ac6-32a6-52df-9c1e-7313158a40ac', 'tech-software-development', 'Can you <b>loop me in</b> on the thread when you hear back?', 'A2', 109),
  ('ed1d9976-75b2-52bf-b06b-dd0620ed0f66', 'tech-software-development', 'I should''ve <b>looped</b> design <b>in</b> earlier — that''s on me.', 'B2', 110),
  ('7dc69eed-22b3-597e-b13a-ce5c18d686a1', 'tech-software-development', '<b>Ping</b> me when the build''s green and I''ll deploy.', 'C1', 111),
  ('b71a9d04-851a-5150-8e98-5b035baebd14', 'tech-software-development', 'I''ll <b>ping</b> her on Slack real quick.', 'B1', 112),
  ('3d4baec9-7e04-5ab5-9ff3-b89125933746', 'tech-software-development', 'Just <b>ping</b> the channel if you get stuck.', 'B1', 113),
  ('a0e17a93-2cb8-5ef3-be35-30fb55d265d8', 'meetings', 'Okay, I think everyone''s here, so <b>let''s get started</b>.', 'B1', 0),
  ('5daa5ae4-5b19-50bb-817d-270620062c4c', 'meetings', 'It''s a little past two, so <b>let''s get started</b> and we''ll catch the others up later.', 'C1', 1),
  ('a4a315c0-830e-5afb-9a9c-62ac21d22d51', 'meetings', 'Alright, <b>let''s get started</b> — we''ve got a lot to cover today.', 'B2', 2),
  ('c97e49e5-3f89-533a-bf5c-f56d957102ab', 'meetings', '<b>Thanks everyone for joining</b> — I know it''s early on the West Coast.', 'B2', 3),
  ('8666df9e-b672-5976-8a30-493739df4867', 'meetings', '<b>Thanks everyone for joining</b> today, especially on such short notice.', 'B2', 4),
  ('932d5229-7898-5cb9-aac5-fbf90594525c', 'meetings', 'Hey all, <b>thanks everyone for joining</b>. Let''s give it a sec for a couple more people to hop on.', 'C2', 5),
  ('ca307a70-21e9-564e-a63f-218c56687f64', 'meetings', 'We''re short on time, so <b>let''s dive in</b>.', 'B1', 6),
  ('8dad4983-48ac-5394-9c08-885dad7a120a', 'meetings', 'No need for long intros — <b>let''s dive in</b>.', 'B2', 7),
  ('9dcf2278-e43d-5df0-88f8-6678c7e3efeb', 'meetings', 'Great, everyone''s got the deck in front of them? <b>Let''s dive in</b>.', 'C1', 8),
  ('2dacaa62-c20f-5ce1-a041-3b9a8e7342f4', 'meetings', '<b>Let''s kick things off</b> with a quick update from marketing.', 'B2', 9),
  ('4c7e6856-298f-5e76-b8f9-71090f0826e4', 'meetings', 'Alright, <b>let''s kick things off</b> — Sarah, do you want to start?', 'B2', 10),
  ('4bdaabfd-0a2b-53f4-91cf-0593c367c9b6', 'meetings', 'To save time, <b>let''s kick things off</b> with the numbers and take questions after.', 'B1', 11),
  ('c6dd3c0f-3889-5339-8c97-2b60f3a8fc74', 'meetings', 'Let''s <b>go around the room</b> and have everyone give a quick status update.', 'B2', 12),
  ('0b633a94-29f4-5786-9d7f-799377fb5ebd', 'meetings', 'Before we start, let''s <b>go around the room</b> so the new folks can introduce themselves.', 'C1', 13),
  ('da34770a-d383-5ecb-86f3-06ff79c63b6b', 'meetings', 'We''ll <b>go around the room</b>, and if you''re remote just jump in when I call your name.', 'C1', 14)
insert into public.sentences (id, deck_id, content, level_id, position) values
  ('6f3a9e16-8894-52b3-b095-a2c3e06dca0f', 'meetings', 'For anyone who missed last week, here''s a <b>quick recap</b>.', 'B2', 15),
  ('480feae8-7a48-5839-95f7-f949e178aeef', 'meetings', 'Let me give you a <b>quick recap</b> of where we landed.', 'B1', 16),
  ('9244fa20-b7b3-5323-b011-4aaa0cdd1094', 'meetings', '<b>Quick recap</b> before we move on: we agreed to push the launch to March.', 'C1', 17),
  ('0b6e015f-9ce2-53bb-9499-da5fb524bf7f', 'meetings', '<b>For those just joining</b>, we''re on the second agenda item.', 'B1', 18),
  ('72961afe-3e54-5fdf-a4d2-65fe7c7cb22f', 'meetings', '<b>For those just joining us</b>, I''ll repeat the question that came up.', 'B1', 19),
  ('f51b67a9-24ec-512d-a450-abc5536941ae', 'meetings', '<b>For those just joining</b>, we wrapped up the budget discussion a minute ago.', 'B2', 20),
  ('1b1ef251-d0ce-50d1-b6cc-807bb517fc38', 'meetings', '<b>First on the agenda</b> is the Q3 roadmap.', 'A2', 21),
  ('6b25cf2e-38c4-5241-b3c4-64ac4d96140c', 'meetings', 'So, <b>first on the agenda</b> — let''s talk about the budget.', 'B1', 22),
  ('0986822b-01a1-5086-b7b6-df1278029309', 'meetings', 'We''ve got three things today; <b>first up on the agenda</b> is hiring.', 'B2', 23),
  ('ed000ceb-2d50-5fc2-9a96-3fca17b8743d', 'meetings', '<b>Let''s give it a couple minutes</b> for people to trickle in.', 'B1', 24),
  ('c1d66683-5224-50ab-8e2c-bf989566bb5f', 'meetings', 'It''s just us so far — <b>let''s give it a couple minutes</b>.', 'B2', 25),
  ('880cf696-e0e5-56e1-b215-ee1e76d69553', 'meetings', '<b>Let''s give it a couple minutes</b> and then we''ll get going.', 'B2', 26),
  ('54c1ff71-32b7-55f0-8a60-d2969316dc4e', 'meetings', 'Before we start, just <b>a couple of housekeeping items</b> — this call is being recorded.', 'B2', 27),
  ('461d3fdb-ae20-5967-9af0-d11c5ae5c73f', 'meetings', '<b>A couple of housekeeping items</b> first: mics on mute, questions in the chat.', 'C1', 28),
  ('3d160d89-f34e-5d8a-a31d-026b33b60674', 'meetings', 'Quick note, <b>a couple of housekeeping items</b> and then we''ll jump in.', 'B2', 29),
  ('8056e22e-1912-5f02-a699-11aec715f14c', 'meetings', '<b>Can everyone hear me okay?</b> Great, let''s get going.', 'C1', 30),
  ('fe399aee-8b87-5fd1-a6b3-230738ce8f08', 'meetings', 'Sorry, one sec — <b>can everyone hear me okay</b> now?', 'C1', 31),
  ('50623620-55ae-5040-a5ae-25f67a92898c', 'meetings', '<b>Can everyone hear me okay?</b> Give me a thumbs up if the audio''s good.', 'C2', 32),
  ('c25bd371-987c-5efb-ac42-9417cddd6b31', 'meetings', 'Sorry, <b>let me jump in</b> here real quick — I think we''re missing one thing.', 'C1', 33),
  ('2633c734-cb16-5a15-9761-9855acf3dac3', 'meetings', 'Can I <b>jump in</b>? I''ve actually dealt with this exact issue before.', 'C1', 34),
  ('ff4e9f19-0db5-53a5-b616-8807b6ff763d', 'meetings', 'Before we move on, <b>let me jump in</b> with a quick clarification.', 'B1', 35),
  ('e818b5ae-e53f-552e-a7ff-9ddacc62c106', 'meetings', 'Just to <b>piggyback on that</b>, we saw the same pattern in the Q2 numbers.', 'B1', 36),
  ('49363b30-12ff-59e6-8527-6ad62938e4a1', 'meetings', 'Can I <b>piggyback on</b> what Dana said? It ties into the timeline.', 'B2', 37),
