  ('319ae778-fe8e-5be6-9a25-ed8d4e6c8c30', 'emotions-opinions', 'Don''t <b>freak out</b>, but I think I dented the car.', 'C1', 13),
  ('8356e2cb-7c7b-5745-a2f6-9cf024deb84c', 'emotions-opinions', 'I''m <b>freaking out</b> - I just got the job!', 'A2', 14),
  ('348cf6ec-a246-5225-ba70-f79b2bba7a2d', 'emotions-opinions', '''How''s it going?'' ''Oh, <b>can''t complain</b> - busy but good.''', 'C1', 15),
  ('7cce403a-3cc0-5227-88e0-2d48c1a72c00', 'emotions-opinions', 'Business has been steady lately, <b>can''t complain</b>.', 'B2', 16),
  ('a3350f21-f595-5539-8da3-9054f8ef0bcb', 'emotions-opinions', '''How was the trip?'' ''Honestly, <b>can''t complain</b> - the weather was perfect.''', 'C1', 17),
