  ('395e849f-f59c-5cb8-9835-ca2a445120e5', 'emotions-opinions', 'I <b>can''t wait</b> for the weekend.', 'A2', 33),
  ('e2d54497-50d4-51c4-986b-1098ff704f1b', 'emotions-opinions', 'We <b>can''t wait</b> to see you guys next month!', 'B1', 34),
  ('3c40cff5-cc88-5a10-9496-80ce58aee0b7', 'emotions-opinions', 'She <b>can''t wait</b> to move into the new place.', 'B1', 35),
