  ('fed2676d-84ce-5ab9-bb0e-7268099d2729', 'emotions-opinions', 'Don''t get so <b>worked up</b> over a comment on the internet.', 'B1', 42),
  ('5d6fc277-bd8d-5004-ace5-54324c63c783', 'emotions-opinions', 'He was all <b>worked up</b> about the referee''s call.', 'A1', 43),
  ('f300a92f-268d-53d9-8539-a4495ab4e59b', 'emotions-opinions', 'I got myself <b>worked up</b> over nothing - the meeting was fine.', 'B1', 44),
  ('8de5509b-f071-504f-b6f4-26d458ce52b8', 'emotions-opinions', 'We broke up months ago - I''m totally <b>over it</b> now.', 'B1', 45),
